/**
 * Sortie Squadron Attrition
 * Formula: (1d6 / 2) * 1d6
 */

async function rollSortie() {
    // Roll 4d6 total
    const r = await Promise.all([
        new Roll("1d6").evaluate(), // Dest Die A
        new Roll("1d6").evaluate(), // Dest Die B
        new Roll("1d6").evaluate(), // Dam Die A
        new Roll("1d6").evaluate()  // Dam Die B
    ]);

    // Apply formula: ceil(Die A / 2) * Die B
    const destTotal = Math.ceil(r[0].total / 2) * r[1].total;
    const damTotal = Math.ceil(r[2].total / 2) * r[3].total;

    let message = `
        <div style="text-align:center"><h2 style="color:green">Sortie Squadron</h2></div>
        <hr>
        <div style="font-size: 1.2em; line-height: 1.6;">
            <span style="color:green"><b>&bull; Destroyed:</b></span> ${destTotal}<br>
            <span style="color:green"><b>&bull; Damaged:</b></span> ${damTotal}
        </div>
    `;

    ChatMessage.create({ content: message });
}

rollSortie();

/**
 * Basic Campaign System Macro
 */

