    { name: "Battalion", mod: 3, lowerMod: 1, rolls: 3 },
    { name: "Regiment", mod: 9, lowerMod: 3, rolls: 3 },
    { name: "Larger Force", mod: 9, lowerMod: 9, rolls: 1 } // Rolls handled per regiment in logic
