const unitExp = { "Green": 1, "Regular": 2, "Veteran": 3, "Elite": 4 };

// --- DATA TABLES ---
const resistanceTable = {
    "Cadre Duty":       ["A","H","M","L","L","N","L","L","M","H","A"],
    "Garrison Duty":    ["A","H","M","L","N","N","N","L","M","H","A"],
