    "Defensive Campaign":["A","A","H","H","M","L","M","H","H","A","A"],
    "Planetary Assault": ["H","H","L","M","M","A","M","M","L","H","H"],
    "Relief Duty":      ["A","H","L","M","M","H","M","M","L","H","A"],
    "Riot Duty":        ["H","H","L","L","N","M","N","L","L","H","H"],
    "Recon Raid":       ["A","A","L","M","L","H","L","M","L","A","A"],
