// Simplified Outcome Mapping (Mission -> Resistance -> Roll Result)
const missionOutcomeTables = {
    "Objective Raid": { "L": "NMLKIFDCBAA", "M": "NMLKJHEDCBA", "H": "ONLKIIGEDCB", "A": "PONMLKIGEDC" },
    "Diversionary Raid": { "L": "NM LKJH FEDCB", "M": "NM LKJ GEDCCB", "H": "QN PMLK JHEDC", "A": "QP ONML KJFED" },
    "Relief Duty": { "L": "ONMKIGEDCBA", "M": "PONMJ IHEEDCB", "H": "PN MJIHEEDDB", "A": "QPONMKIGEDD" },
    "Riot Duty": { "N": "MLJIHGEEEED", "L": "NLMJHGEEEED", "M": "ONMLKH FEEEED", "H": "PONMLKHFEED" },
    "Siege Campaign": { "L": "MKJIGFEDCBA", "M": "ONMLKIGDFCB", "H": "PONMLKIHFEC" },
    "Guerrilla Warfare": { "N": "ONM JHEEEEDCB", "L": "PON MJHEEEEDCB", "M": "QPON MJHEEDCB", "H": "QQ PONMJHEDB" },
    "Cadre Duty": { "N": "NMM LJ IHEEED", "L": "NMM MKIEEEED", "M": "OMMMKIEEEEC", "H": "NNMMM KIEEEDDC", "A": "ONMMMKIEEEDC" },
    "Garrison Duty": { "N": "MMM MIEE EEE", "L": "NMMM J I HEEED", "M": "OMMK J I HGEEEDC", "H": "ONML K I GFEEEDC", "A": "PNLK J I HGFEDB" },
    "Security Duty": { "N": "MMM MKI GEEEE", "L": "MMML J I H FEEEED", "M": "NMMK J I H GEEEED", "H": "OMML K I G FEEEEC", "A": "PNMM L I FEEEEDB" },
    "Offensive Campaign": { "L": "PNMMKIG EDBA", "M": "QON ML I FE DCBA", "H": "QQPO NM I E DCBAA", "A": "QQPO MI E CBAA" },
    "Defensive Campaign": { "L": "PONM KI F E EDC", "M": "PONM LI E E EDCCB", "H": "PPO NM MI E E EDCCB", "A": "QPON MH E D CB A" },
    "Planetary Assault": { "L": "QQPO NI DCBAA", "M": "QPON MI ED CBAA", "H": "QPON MI ED BBAA", "A": "QQPN MI ED BAA" },
    "Recon Raid": { "L": "NLJI EE ED CBA", "M": "QNMM K I GEDCB", "H": "QONM L K I GEDCB", "A": "QPON N M L I GEC" }
};

const outcomeDescriptions = {
    "A": { res: "win", rep: 6, dng: 5, slv: 6, dst: 5, plu: 10 },
    "B": { res: "win", rep: 5, dng: 5, slv: 6, dst: 5, plu: 10 },
    "C": { res: "win", rep: 4, dng: 5, slv: 6, dst: 5, plu: 9 },
    "D": { res: "win", rep: 3, dng: 6, slv: 7, dst: 6, plu: 9 },
    "E": { res: "win", rep: 2, dng: 6, slv: 7, dst: 6, plu: 8 },
    "F": { res: "uncompleted", rep: 1, dng: 6, slv: 7, dst: 6, plu: 7 },
    "G": { res: "uncompleted", rep: 0, dng: 7, slv: 8, dst: 7, plu: 7 },
    "H": { res: "uncompleted", rep: 0, dng: 7, slv: 8, dst: 7, plu: 6 },
    "I": { res: "uncompleted", rep: 0, dng: 7, slv: 8, dst: 7, plu: 6 },
    "J": { res: "uncompleted", rep: 0, dng: 7, slv: 8, dst: 7, plu: 5 },
    "K": { res: "uncompleted", rep: 0, dng: 7, slv: 8, dst: 7, plu: 5 },
    "L": { res: "uncompleted", rep: -1, dng: 8, slv: 9, dst: 8, plu: 5 },
    "M": { res: "loss", rep: -2, dng: 8, slv: 9, dst: 8, plu: 4 },
    "N": { res: "loss", rep: -3, dng: 8, slv: 9, dst: 8, plu: 4 },
    "O": { res: "loss", rep: -4, dng: 9, slv: 10, dst: 9, plu: 4 },
    "P": { res: "loss", rep: -5, dng: 9, slv: 10, dst: 9, plu: 4 },
    "Q": { res: "loss", rep: -6, dng: 9, slv: 10, dst: 9, plu: 4 }
};

// --- DIALOG ---
let content = `
<div class="form-group">
    <label>Mission Type:</label>
    <select id="mission">${missions.map(m => `<option value="${m}">${m}</option>`).join('')}</select>
</div>
<div class="form-group">
    <label>Unit Size:</label>
    <select id="unitSize">${unitSizes.map((s, i) => `<option value="${i}">${s.name}</option>`).join('')}</select>
</div>
<div class="form-group">
    <label>Regiments (if Larger Force):</label>
    <input type="number" id="regCount" value="1">
</div>
<div class="form-group">
    <label>Experience:</label>
    <select id="experience">${Object.keys(unitExp).map(e => `<option value="${e}">${e}</option>`).join('')}</select>
</div>`;

new Dialog({
    title: "Basic Campaign System",
    content: content,
    buttons: {
        roll: {
            label: "Roll Month",
            callback: async (html) => {
                const mission = html.find('#mission').val();
                const sizeIdx = html.find('#unitSize').val();
                const expKey = html.find('#experience').val();
                const regCount = parseInt(html.find('#regCount').val()) || 1;

                const unitSizeObj = unitSizes[sizeIdx];
                const expVal = unitExp[expKey];

                // 1. Enemy Resistance Roll
                const resRoll = await new Roll("2d6").evaluate();
                const resCode = resistanceTable[mission][resRoll.total - 2];
                const resName = { "A": "Assault", "H": "Heavy", "M": "Medium", "L": "Light", "N": "None" }[resCode];

                // 2. Outcome Roll
                const outRoll = await new Roll("2d6").evaluate();
                const outcomeString = missionOutcomeTables[mission][resCode];
                const outcomeCode = outcomeString.charAt(outRoll.total - 2).trim();
                const data = outcomeDescriptions[outcomeCode];

                // 3. Calculated Stats
                const dangerRating = 7 - data.dng;

                // 4. Damage/Plunder Logic
                const processMetric = async (target, isPlunder = false) => {
                    let totalUnits = 0;
                    let rollCount = (unitSizeObj.name === "Larger Force") ? regCount : unitSizeObj.rolls;

                    for (let i = 0; i < rollCount; i++) {
                        const r = await new Roll("2d6").evaluate();
                        const total = isPlunder ? (r.total - expVal) : (r.total + expVal);

                        const success = isPlunder ? (total <= target) : (total < target); // "Target or higher" is failure for damaged/destroyed

                        if (success) {
                            const valRoll = isPlunder ? (await new Roll("2d6").evaluate()).total * 10000 : (await new Roll("1d6").evaluate()).total;
                            totalUnits += Math.ceil(valRoll * unitSizeObj.lowerMod);
                        }
                    }
                    return totalUnits;
                };

                const damaged = await processMetric(data.slv);
                const destroyed = await processMetric(data.dst);
                const plunder = await processMetric(data.plu, true);

                // --- CHAT OUTPUT ---
                let chatContent = `
                    <div class="dice-roll">
                        <div class="dice-result">
                            <h3 class="dice-total">Campaign Results: ${outcomeCode}</h3>
                            <div class="dice-formula">Mission: ${mission} vs ${resName} Force</div>
                            <hr>
                            <p><b>Result:</b> ${data.res.toUpperCase()}</p>
                            <p><b>Reputation:</b> ${data.rep > 0 ? '+' : ''}${data.rep}</p>
                            <p><b>Danger Level:</b> ${dangerRating > 0 ? '+' : ''}${dangerRating}</p>
                            <p><b>Units Damaged:</b> ${damaged}</p>
                            <p><b>Units Destroyed:</b> ${destroyed}</p>
                            <p><b>Plunder Acquired:</b> ${plunder.toLocaleString()} C-Bills</p>
                        </div>
                    </div>
                `;

                ChatMessage.create({ content: chatContent });
            }
        }
    }
}).render(true);

(async () => {
  // -----------------------------
  // CONFIG & MAPPING
  // -----------------------------
  const ITEM_TYPE = "item";
  const CATEGORIES = ["Trait", "Skill"];

  const FOLDER_COLORS = {
    Trait: "#b35900",
    Skill: "#008000"
  };

  const ICONS = {
    Trait: "modules/mechwarrior-rpg-homebrew/icons/Opposed Attr Checks.png",
    Skill: "modules/mechwarrior-rpg-homebrew/icons/Skill Check.png"
  };

  const FIELD_MAPS = {
    "Skill": {
      "name": "name",
      "attr_1": "a1",
      "attr_2": "a2",
      "skill_tn": "tn",
      "skill_type": "c",
      "skill_text": "description"
    },
    "Trait": {
      "name": "name",
      "trait_level": "tp",
      "trait_description": "description"
    }
  };

  // -----------------------------
  // FOLDER MANAGEMENT
  // -----------------------------
  async function getOrCreateFolder(folderName) {
    let folder = game.folders.find(f => f.name === folderName && f.type === "Item");
    if (!folder) {
      folder = await Folder.create({ 
        name: folderName, 
        type: "Item", 
        color: FOLDER_COLORS[folderName] || "#000000" 
      });
    }
    return folder.id;
  }

  // -----------------------------
  // HTML GENERATORS (Original Box Style)
  // -----------------------------
  const TEMPLATES = {
    Skill: (p) => {
      const links = (p.a1 && p.a2) ? `${p.a1}/${p.a2}` : (p.a1 || p.a2 || "—");
      const tnc = `${p.tn || '8'}/${p.c || 'B'}`;

      return `
      <div style="border:2px solid #008000; background:#ffffff; padding:8px; font-family: sans-serif; color: #000000;">
        <h3 style="border-bottom:2px solid #008000; color:#000000; margin:0; text-transform:uppercase;">${p.name}</h3>
        <table style="width:100%; font-size:0.9em; margin:5px 0; color: #000000; border-collapse:collapse;">
          <tr>
            <td style="width:50%;"><b>Attributes:</b> ${links.toUpperCase()}</td>
            <td style="width:50%; text-align:right;"><b>TN/C:</b> ${tnc}</td>
          </tr>
        </table>
        <div style="margin-top:8px; border-top:1px solid #000000; font-size:0.95em; color: #000000; padding-top:5px;">
          ${p.description || ""}
        </div>
      </div>`;
    },

    Trait: (p) => `
      <div style="border:2px solid #b35900; background:#ffffff; padding:8px; font-family: sans-serif; color: #000000;">
        <h3 style="border-bottom:2px solid #b35900; color:#000000; margin:0; text-transform:uppercase;">${p.name}</h3>
        <p style="font-size:0.9em; margin:5px 0; color: #000000;"><b>Points (TP):</b> ${p.tp || '0'}</p>
        <div style="margin-top:8px; border-top:1px solid #000000; font-size:0.95em; color: #000000; padding-top:5px;">
          ${p.description || ""}
        </div>
      </div>`
  };

  // -----------------------------
  // FILE PICKER & MAIN LOGIC
  // -----------------------------
  const input = document.createElement("input");
  input.type = "file";
  input.accept = ".xml";
  input.onchange = async () => {
    const file = input.files[0];
    if (!file) return;
    const xmlText = await file.text();

    const parser = new DOMParser();
    const xml = parser.parseFromString(xmlText, "text/xml");
    const records = [...xml.querySelectorAll("[tagname^='id-'], *")].filter(n => n.tagName.startsWith("id-"));

    const folderIds = {};
    for (const cat of CATEGORIES) folderIds[cat] = await getOrCreateFolder(cat);

    const itemsToCreate = [];

    for (const record of records) {
      let itemKind = null;
      if (record.querySelector("skill_tn") || record.querySelector("skill_type")) itemKind = "Skill";
      else if (record.querySelector("trait_level") || record.querySelector("trait_description")) itemKind = "Trait";

      if (!itemKind || !FIELD_MAPS[itemKind]) continue;

      const name = record.querySelector("name")?.textContent?.trim() ?? record.tagName;
      const rawData = extractRawData(record);

      const systemProps = { name: name };
      const map = FIELD_MAPS[itemKind];
      for (let [xmlTag, csbKey] of Object.entries(map)) {
        systemProps[csbKey] = rawData[xmlTag] !== undefined ? rawData[xmlTag] : "";
      }

      const finalHTML = TEMPLATES[itemKind](systemProps);

      itemsToCreate.push({
        name,
        type: ITEM_TYPE,
        img: ICONS[itemKind] || "icons/svg/item-bag.svg",
        folder: folderIds[itemKind],
        system: {
          description: finalHTML,
          props: systemProps
        }
      });
    }

    if (itemsToCreate.length > 0) {
      await Item.createDocuments(itemsToCreate);
      ui.notifications.info(`Imported ${itemsToCreate.length} items using original box style.`);
    }
  };
  input.click();

  function extractRawData(recordNode) {
    const data = {};
    for (const el of recordNode.children) {
      let value = el.textContent?.trim();
      if (el.getAttribute("type") === "number") value = Number(value) || 0;
      if (el.getAttribute("type") === "formattedtext") value = el.innerHTML.trim();
      data[el.tagName] = value;
    }
    return data;
  }
})();

/**
 * Campaign Resolution Macro
 * Features: 
 * - Terminology: Friendly (Blue) / Enemy (Red) across all phases.
 * - Maneuver: Separate F/E Maneuver Strength & Independent Attrition.
 * - Combat: Manual Scale selection + Larger Force (Regiment count).
 * - Feedback: Color-coded notes for phase transitions.
 */

const getResult = (roll, ratioIdx, table) => table[Math.min(Math.max(roll, 2), 12)][ratioIdx];
const ratios = ["1/3", "1/2.5", "1/2", "1/1.5", "1/1", "1.5/1", "2/1", "2.5/1", "3/1"];

const scales = {
    "roll": { name: "Roll for Scale", mod: 0 },
    "squad": { name: "Squad", mod: 0.33 },
    "lance": { name: "Lance/Platoon", mod: 0.66 },
    "company": { name: "Company", mod: 1.0 },
    "battalion": { name: "Battalion", mod: 3.0 },
    "regiment": { name: "Regiment", mod: 9.0 },
    "larger": { name: "Larger Force (Multi-Regiment)", mod: 9.0 }
};

const aerospaceGrid = { 2: ["ES","ES","ES","ES","ES","A","A","A","A"], 3: ["ES","ES","ES","ES","ES","A","A","A","FS"], 4: ["ES","ES","ES","ES","A","A","A","A","FS"], 5: ["ES","ES","ES","ES","A","A","A","FS","FS"], 6: ["ES","ES","ES","A","A","A","A","FS","FS"], 7: ["ES","ES","ES","A","A","A","FS","FS","FS"], 8: ["ES","ES","A","A","A","A","FS","FS","FS"], 9: ["ES","ES","A","A","A","FS","FS","FS","FS"], 10: ["ES","A","A","A","A","FS","FS","FS","FS"], 11: ["ES","A","A","A","FS","FS","FS","FS","FS"], 12: ["A","A","A","A","FS","FS","FS","FS","FS"] };
const maneuverGrid = { 2: ["DecE","DecE","DecE","DecE","DecE","DecE","DecE","DecE","DecE"], 3: ["DecE","DecE","DecE","Con","Con","Att","SK","Bat","NP"], 4: ["DecE","Con","Con","Con","Att","SK","Bat","NP","Bat"], 5: ["Con","Con","Att","Att","SK","Bat","NP","Bat","SK"], 6: ["Att","Att","Att","SK","Bat","NP","Bat","SK","Att"], 7: ["Att","Att","SK","Bat","NP","Bat","SK","Att","Att"], 8: ["Att","SK","Bat","NP","Bat","SK","Att","Att","Att"], 9: ["SK","Bat","NP","Bat","SK","Att","Att","Con","Con"], 10: ["Bat","NP","Bat","SK","Att","Con","Con","Con","DecF"], 11: ["NP","Bat","SK","Att","Con","Con","DecF","DecF","DecF"], 12: ["DecF","DecF","DecF","DecF","DecF","DecF","DecF","DecF","DecF"] };
const combatGrid = { 2: ["J/A","J/A","J/A","I/B","I/B","I/C","H/C","H/D","H/D"], 3: ["J/A","I/A","I/B","H/B","H/C","H/C","G/D","F/E","F/F"], 4: ["I/A","I/B","H/B","H/C","G/C","G/D","F/E","F/F","E/F"], 5: ["I/B","H/B","H/C","G/C","G/D","F/E","F/F","E/F","D/G"], 6: ["H/B","H/C","G/C","G/D","F/E","F/F","E/F","D/G","C/G"], 7: ["H/C","G/C","G/D","F/E","F/F","E/F","D/G","C/G","C/H"], 8: ["G/C","G/D","F/E","F/F","E/F","D/G","C/G","C/H","B/H"], 9: ["G/D","F/E","F/F","E/F","D/G","C/G","C/H","B/H","B/I"], 10: ["F/E","F/F","E/F","D/G","C/G","C/H","B/H","B/I","A/I"], 11: ["F/F","E/F","D/G","C/H","C/H","B/H","B/I","A/I","A/J"], 12: ["D/H","D/H","C/H","C/I","B/I","B/I","A/J","A/J","A/J"] };

const combatTableDefinitions = { "A": { out: "Win*", rep: 5, salv: "1d6/3", dest: "1d6/3" }, "B": { out: "Win*", rep: 3, salv: "1d6/2", dest: "1d6/2" }, "C": { out: "Win*", rep: 2, salv: "1d6/2", dest: "1d6/2" }, "D": { out: "Draw*", rep: 1, salv: "1d6", dest: "1d6" }, "E": { out: "Draw*", rep: 0, salv: "1d6", dest: "1d6" }, "F": { out: "Draw", rep: 0, salv: "1d6+1", dest: "1d6+1" }, "G": { out: "Draw", rep: -1, salv: "1d6+2", dest: "1d6+2" }, "H": { out: "Loss", rep: -2, salv: "1d6+2", dest: "1d6+2" }, "I": { out: "Loss", rep: -3, salv: "1d6+3", dest: "1d6+3" }, "J": { out: "Loss", rep: -5, salv: "2d6", dest: "2d6" } };

const getEngagedModifier = (roll) => {
    if (roll <= 3) return scales.squad;
    if (roll <= 5) return scales.lance;
    if (roll <= 7) return scales.company;
    if (roll <= 9) return scales.battalion;
    return scales.regiment;
};

async function runPhase(phaseName) {
    let html = `<div class="form-group"><label>Ratio (Friendly/Enemy):</label><select id="ratio">
        ${ratios.map((r, i) => `<option value="${i}" ${i === 4 ? "selected" : ""}>${r}</option>`).join("")}
    </select></div>
    <div class="form-group"><label>Tactics Mod:</label><input type="number" id="tac" value="0"></div>`;

    if(phaseName === "Maneuver Operations") {
        html += `<div class="form-group"><label>Friendly Maneuver Strength:</label><input type="number" id="fStr" value="0"></div>
                 <div class="form-group"><label>Enemy Maneuver Strength:</label><input type="number" id="eStr" value="0"></div>`;
    }

    if(phaseName === "Combat Operations") {
        html += `<div class="form-group"><label>Force Scale:</label>
        <select id="scaleSelect" onchange="const larger = document.getElementById('largerInput'); if(larger) larger.style.display = (this.value === 'larger') ? 'flex' : 'none'">
            ${Object.entries(scales).map(([k, v]) => `<option value="${k}">${v.name}</option>`).join("")}
        </select></div>
        <div id="largerInput" class="form-group" style="display:none;"><label>Number of Regiments:</label><input type="number" id="regCount" value="1"></div>
        <div class="form-group"><label>Battle? (+5 to EE Roll):</label><input type="checkbox" id="bat"></div>`;
    }

    new Dialog({
        title: `${phaseName}`,
        content: html,
        buttons: { roll: { label: "Execute", callback: async (h) => {
            const rIdx = parseInt(h.find("#ratio").val());
            const tac = parseInt(h.find("#tac").val());
            const rollResult = await new Roll(`2d6 + ${tac}`).evaluate();
            let message = `<div style="text-align:center"><h2>${phaseName}</h2></div>
                           <b>Force Ratio:</b> ${ratios[rIdx]}<br>
                           <b>Roll Result:</b> ${rollResult.total}<hr>`;

            if(phaseName === "Aerospace Operations") {
                const res = getResult(rollResult.total, rIdx, aerospaceGrid);
                const rls = await Promise.all(Array.from({length: 8}, () => new Roll("1d6").evaluate()));
                let fDest, fDam, eDest, eDam;
                const full = (r1, r2) => r1.total * r2.total;
                const half = (r1, r2) => Math.ceil(r1.total/2) * r2.total;
                if(res === "ES") { fDest = full(rls[0], rls[1]); fDam = full(rls[2], rls[3]); eDest = half(rls[4], rls[5]); eDam = half(rls[6], rls[7]); } 
                else if(res === "A") { fDest = half(rls[0], rls[1]); fDam = half(rls[2], rls[3]); eDest = half(rls[4], rls[5]); eDam = half(rls[6], rls[7]); } 
                else { fDest = half(rls[0], rls[1]); fDam = half(rls[2], rls[3]); eDest = full(rls[4], rls[5]); eDam = full(rls[6], rls[7]); }
                message += `<b>Outcome:</b> ${res}<br><br>
                           <span style="color:blue"><b>Friendly:</b></span> ${fDest} Dest / ${fDam} Dam<br>
                           <span style="color:red"><b>Enemy:</b></span> ${eDest} Dest / ${eDam} Dam`;
            } 
            else if(phaseName === "Maneuver Operations") {
                const res = getResult(rollResult.total, rIdx, maneuverGrid);
                message += `<b>Outcome:</b> ${res}`;
                if(res === "Att") {
                    const fStr = parseInt(h.find("#fStr").val());
                    const eStr = parseInt(h.find("#eStr").val());
                    const fDmgRoll = await new Roll(`2d6 - 2 + ${fStr}`).evaluate();
                    const eDmgRoll = await new Roll(`2d6 - 2 + ${eStr}`).evaluate();
                    message += `<br><br><span style="color:blue"><b>Friendly Damaged:</b></span> ${Math.max(0, fDmgRoll.total)}<br>
                               <span style="color:red"><b>Enemy Damaged:</b></span> ${Math.max(0, eDmgRoll.total)}`;
                }
                if (["NP", "Att", "SK", "Bat"].includes(res)) {
                    message += `<hr><p style="color:green"><b>Action Required:</b> Result is ${res}. Proceed to <b>Combat Operations Phase</b>.</p>`;
                } else if (res === "Con") {
                    message += `<hr><p style="color:blue"><b>Note:</b> Continued Campaign. Proceed to <b>Campaign Resolution Phase</b>.</p>`;
                }
            } 
            else {
                const selectedScale = h.find("#scaleSelect").val();
                let sizeObj;
                if (selectedScale === "roll") {
                    const isBattle = h.find("#bat").is(":checked");
                    const eeRoll = await new Roll(`1d6 ${isBattle ? "+ 5" : ""}`).evaluate();
                    sizeObj = getEngagedModifier(eeRoll.total);
                } else if (selectedScale === "larger") {
                    const count = parseInt(h.find("#regCount").val()) || 1;
                    sizeObj = { name: `${count} Regiments`, mod: 9.0 * count };
                } else { sizeObj = scales[selectedScale]; }

                const res = getResult(rollResult.total, rIdx, combatGrid);
                const [fCode, eCode] = res.split("/");
                const fData = combatTableDefinitions[fCode];
                const eData = combatTableDefinitions[eCode];
                const rls = await Promise.all([new Roll(fData.dest).evaluate(), new Roll(fData.salv).evaluate(), new Roll(eData.dest).evaluate(), new Roll(eData.salv).evaluate()]);

                message += `<b>Scale:</b> ${sizeObj.name}<br><br>
                <span style="color:blue"><b>Friendly (${fCode}):</b></span> ${fData.out}, Rep ${fData.rep}<br>
                &bull; ${Math.ceil(rls[0].total * sizeObj.mod)} Destroyed / ${Math.ceil(rls[1].total * sizeObj.mod)} Damaged<br><br>
                <span style="color:red"><b>Enemy (${eCode}):</b></span> ${eData.out}, Rep ${eData.rep}<br>
                &bull; ${Math.ceil(rls[2].total * sizeObj.mod)} Destroyed / ${Math.ceil(rls[3].total * sizeObj.mod)} Damaged`;
            }
            ChatMessage.create({ content: message });
        }}}
    }).render(true);
}

