new Dialog({
    title: "Simple Force Generator (Complex Output)",
    content: template,
    buttons: {
        generate: {
            icon: '<i class="fas fa-dice-d20"></i>',
            label: "Generate Forces",
            callback: async (html) => {
                let finalData = {};
                for (let s of ['f', 'e']) {
                    let name = html.find(`#${s}-name`).val();
                    let mission = html.find(`#${s}-mission`).val();
                    let countIn = parseInt(html.find(`#${s}-count`).val());
                    let manualRaw = html.find(`#${s}-manual`).val().trim();
                    let expL = html.find(`#${s}-exp`).val();
                    let techL = html.find(`#${s}-tech`).val();
                    let tact = parseInt(html.find(`#${s}-tactics`).val()) || await getTacticalSkill();
                    let isClan = clanTechs.includes(techL);
                    let multiplier = techRatings[techL] * expLevels[expL];

                    let manualItems = [];
                    if (manualRaw.length > 0) {
                        manualRaw.split(/\s*,\s*/).forEach(t => {
                            let m = t.match(/^(.+?)(?:\s*x(\d+))?$/i);
                            if (m) {
                                let type = m[1].trim(); let c = parseInt(m[2]) || 1;
                                for (let i = 0; i < c; i++) manualItems.push(type);
                            }
                        });
                    }

                    let regCount = countIn === 0 ? (manualItems.length > 0 ? manualItems.length : commitmentTable[mission][(await new Roll("2d6").evaluate()).total - 2]) : countIn;
                    let regDetails = [];
                    let tA = 0, tM = 0, tC = 0, compSum = {};

                    for (let i = 0; i < regCount; i++) {
                        let type = (i < manualItems.length) ? manualItems[i] : compositionTable[mission][(await new Roll("2d6").evaluate()).total];
                        if (!unitTypes.includes(type)) type = "Mech";

                        compSum[type] = (compSum[type] || 0) + 1;
                        let r1 = (await new Roll("1d6").evaluate()).total - 1;
                        let r2 = (await new Roll("1d6").evaluate()).total - 1;
                        let val = valueTables[type][r1][r2];
                        let parts = val.toString().includes('/') ? val.split('/').map(Number) : [val, 0, 0];

                        let a = Math.ceil(parts[0] * multiplier), m = Math.ceil(parts[1] * multiplier), c = Math.ceil(parts[2] * multiplier);
                        regDetails.push({ id: i + 1, type, a, m, c });
                        tA += a; tM += m; tC += c;
                    }
                    finalData[s] = { name, mission, expL, techL, multiplier, tact, regCount, isClan, compSum, regDetails, tA, tM, tC };
                }
                output(finalData);
            }
        }
    },
    render: (html) => {
        html.find('#syntax-help').on('click', () => {
            new Dialog({ title: "Manual Entry Syntax", content: `<div style="padding:10px;"><p><b>Rules:</b></p><ul><li>Separate units with <b>commas</b>.</li><li>Spaces allowed (e.g., <i>Battle Armor</i>).</li><li>Use <b>xN</b> (e.g., <i>Mech x2</i>).</li></ul></div>`, buttons: { ok: { label: "Got it" } } }).render(true);
        });
        html.find('.tech-select').on('change', (e) => {
            const s = e.currentTarget.dataset.side;
            const c = clanTechs.includes(e.currentTarget.value);
            html.find(`#${s}-count-label`).text(c ? "Clusters (0=Roll):" : "Regiments (0=Roll):");
        });
    }
}).render(true);

async function output(data) {
    const buildSection = (d, color) => {
        const uName = d.isClan ? "Cluster" : "Regiment";
        const uMan = Math.ceil(d.tM / 100);
        const uCom = Math.ceil(d.tC / 108);

        let listHtml = d.regDetails.map(r => {
            return `<li><b>${uName} ${r.id} (${r.type}):</b> ${r.a} / ${r.m} / ${r.c} (M:${Math.ceil(r.m/100)} C:${Math.ceil(r.c/108)})</li>`;
        }).join('');

        const headerHtml = `
            <div style="border: 1px solid ${color}; padding: 8px; margin-bottom: 10px; border-radius: 4px;">
                <h3 style="color:${color}; margin:0; border-bottom: 1px solid ${color}">${d.name}</h3>
                <b>Mission:</b> ${d.mission} | <b>Exp:</b> ${d.expL} | <b>Tech:</b> ${d.techL}<br>
                <b>Composition:</b> ${Object.entries(d.compSum).map(([k,v])=>`${k}x${v}`).join(', ')}<br>
                <b>Total (A/M/C):</b> ${d.tA} / ${d.tM} / ${d.tC}<br>
                <b>Maneuver Score:</b> ${uMan} | <b>Combat Score:</b> ${uCom}
            </div>`;
        return { header: headerHtml, list: `<ul>${listHtml}</ul>` };
    };

    const blu = buildSection(data.f, 'blue');
    const red = buildSection(data.e, 'red');

    let fullHtml = `<h2>Battle Report</h2>` + blu.header + `<details><summary>Breakdown</summary>${blu.list}</details>` + red.header + `<details><summary>Breakdown</summary>${red.list}</details>`;

    // Post to Chat
    ChatMessage.create({ content: fullHtml });

    // Create Journal with Embedded Page (Matches Complex logic)
    let journal = await JournalEntry.create({ name: `Battle Report: ${data.f.name} vs ${data.e.name}` });
    await journal.createEmbeddedDocuments("JournalEntryPage", [{
        name: "Force Overview", 
        type: "text", 
        text: { content: fullHtml.replace(/details|summary/g, "div"), format: 1 }
    }]);
}

