                else if (total === 11) effect = "−50% Move, −50% TMM*†";
                else effect = "Unit immobilized";

                ChatMessage.create({ 
                    content: `<b>Motive Systems Roll:</b><div class="dice-tooltip">Roll: ${roll.total} + Mod: ${mod} = ${total}</div><h4 class="dice-total">${effect}</h4>` 
                });
            }
        }
    }
}).render(true);

