new Dialog({
    title: "Complex Force Generator",
    content: template,
    buttons: {
        generate: {
            icon: '<i class="fas fa-dice-d20"></i>',
            label: "Generate Forces",
            callback: async (html) => {
                let finalData = {};
                for (let s of ['f', 'e']) {
                    let sideIdx = (s === 'f') ? 0 : 1;
                    let name = html.find(`#${s}-name`).val();
                    let mission = html.find(`#${s}-mission`).val();
                    let regInput = parseInt(html.find(`#${s}-count`).val());
                    let manualRaw = html.find(`#${s}-manual`).val().trim();
                    let expL = html.find(`#${s}-exp`).val();
                    let techL = html.find(`#${s}-tech`).val();
                    let tact = parseInt(html.find(`#${s}-tactics`).val()) || await getTacticalSkill();
                    let multiplier = techRatings[techL] * expLevels[expL];

                    let isClan = clanTechs.includes(techL);
                    let isHighTech = highTechs.includes(techL);

                    // ADVANCED PARSER
                    let manualItems = [];
                    if (manualRaw.length > 0) {
                        let tokens = manualRaw.split(/\s*,\s*/);
                        tokens.forEach(token => {
                            let match = token.match(/^(.+?)(?:\s*x(\d+))?$/i);
                            if (match) {
                                let type = match[1].trim();
                                let count = parseInt(match[2]) || 1;
                                for (let c = 0; c < count; c++) manualItems.push(type);
                            }
                        });
                    }

                    let regCount = regInput === 0 ? commitmentTable[mission][sideIdx][(await new Roll("2d6").evaluate()).total - 2] : regInput;

                    let totalA = 0, totalM = 0, totalC = 0;
                    let forceCompSummary = {};
                    let regimentDetails = [];

                    for (let i = 0; i < regCount; i++) {
                        let currentRegData = { id: i + 1, type: "", units: {}, a: 0, m: 0, c: 0 };
                        let category = "";

                        if (i < manualItems.length) {
                            let rawItem = manualItems[i];
                            category = Object.keys(orgTable).find(k => k.toLowerCase() === rawItem.toLowerCase()) || rawItem;
                            if (category === "Battle Armor" && !isHighTech && !isClan) category = "Infantry";
                            if (category.toLowerCase() === "air" && isClan) category = "AeroSpace";
                        } else {
                            category = compositionTable[mission][(await new Roll("2d6").evaluate()).total];
                            if (isClan && category === "Air") category = "AeroSpace";
                        }

                        currentRegData.type = category;
                        forceCompSummary[category] = (forceCompSummary[category] || 0) + 1;

                        let unitsLeft = [40, 50, 60, 70, 80, 90, 100, 110, 120, 135, 150][(await new Roll("2d6").evaluate()).total - 2] + (await new Roll("5d6").evaluate()).total;

                        while (unitsLeft > 0) {
                            let orgRoll = (await new Roll("2d6").evaluate()).total;
                            let specific = orgTable[category] ? orgTable[category][orgRoll] : category;

                            if (isClan) {
                                if (specific === "Light LAM") specific = "Light Aerospace Ftr";
                                if (specific === "Medium LAM") specific = "Medium Aerospace Ftr";
                                if (["Infantry", "Jump Infantry", "Motorized Infantry", "Airmobile"].includes(specific)) specific = "Elemental";
                            } else if ((isHighTech && (category === "Infantry" || category === "Battle Armor")) || category === "Battle Armor") {
                                if (["Jump Infantry", "Airmobile"].includes(specific)) specific = "Battle Armor";
                            }

                            let batch = Math.min(unitsLeft, orgRoll);
                            let stats = unitStats[specific] || [0,0,0];
                            currentRegData.a += (stats[0] * batch); currentRegData.m += (stats[1] * batch); currentRegData.c += (stats[2] * batch);
                            currentRegData.units[specific] = (currentRegData.units[specific] || 0) + batch;
                            unitsLeft -= batch;
                        }
                        totalA += currentRegData.a; totalM += currentRegData.m; totalC += currentRegData.c;
                        regimentDetails.push(currentRegData);
                    }
                    finalData[s] = { name, mission, expL, techL, multiplier, tact, regCount, isClan, forceCompSummary, regimentDetails, totalA, totalM, totalC };
                }
                output(finalData);
            }
        }
    },
    render: (html) => {
        html.find('#syntax-help').on('click', () => {
            new Dialog({
                title: "Manual Entry Syntax",
                content: `
                <div style="padding:10px;">
                    <p><b>Rules:</b></p>
                    <ul>
                        <li>Separate units with <b>commas</b>.</li>
                        <li>Spaces are allowed inside names (e.g., <i>Battle Armor</i>).</li>
                        <li>Use <b>xN</b> for multipliers (e.g., <i>Mech x2</i>).</li>
                    </ul>
                    <p><b>Example:</b><br><code>Mech x2, Battle Armor, AeroSpace</code></p>
                </div>`,
                buttons: { ok: { label: "Got it" } }
            }).render(true);
        });
        html.find('.tech-select').on('change', (e) => {
            const side = e.currentTarget.dataset.side;
            const isClan = clanTechs.includes(e.currentTarget.value);
            html.find(`#${side}-count-label`).text(isClan ? "Clusters (0=Roll):" : "Regiments (0=Roll):");
        });
    }
}).render(true);

async function output(data) {
    const buildSection = (d, color) => {
        const unitName = d.isClan ? "Cluster" : "Regiment";
        const totalA = Math.ceil(d.totalA * d.multiplier);
        const totalM = Math.ceil(d.totalM * d.multiplier);
        const totalC = Math.ceil(d.totalC * d.multiplier);
        const uMan = Math.ceil(totalM / 100);
        const uCom = Math.ceil(totalC / 108);

        let regListHtml = d.regimentDetails.map(r => {
            let units = Object.entries(r.units).map(([u, c]) => `${u} x${c}`).join(', ');
            let rA = Math.ceil(r.a * d.multiplier);
            let rM = Math.ceil(r.m * d.multiplier);
            let rC = Math.ceil(r.c * d.multiplier);
            return `<li><b>${unitName} ${r.id} (${r.type}):</b> ${rA} / ${rM} / ${rC} (M:${Math.ceil(rM/100)} C:${Math.ceil(rC/108)})<br><small><i>${units}</i></small></li>`;
        }).join('');

        const headerHtml = `
            <div style="border: 1px solid ${color}; padding: 8px; margin-bottom: 10px; border-radius: 4px;">
                <h3 style="color:${color}; margin:0; border-bottom: 1px solid ${color}">${d.name}</h3>
                <b>Mission:</b> ${d.mission} | <b>Exp:</b> ${d.expL} | <b>Tech:</b> ${d.techL}<br>
                <b>Composition:</b> ${Object.entries(d.forceCompSummary).map(([k,v])=>`${k}x${v}`).join(', ')}<br>
                <b>Total (A/M/C):</b> ${totalA} / ${totalM} / ${totalC}<br>
                <b>Maneuver:</b> ${uMan} | <b>Combat:</b> ${uCom}
            </div>`;
        return { header: headerHtml, list: `<ul>${regListHtml}</ul>` };
    };

    const blu = buildSection(data.f, 'blue');
    const red = buildSection(data.e, 'red');

    let chatHtml = `<h2>Encounter Report</h2>` + blu.header + `<details><summary>Breakdown</summary>${blu.list}</details>` + red.header + `<details><summary>Breakdown</summary>${red.list}</details>`;
    ChatMessage.create({ content: chatHtml });

    let journal = await JournalEntry.create({ name: `Force Gen: ${data.f.name} vs ${data.e.name}` });
    await journal.createEmbeddedDocuments("JournalEntryPage", [{
        name: "Force Report", type: "text", text: { content: chatHtml.replace(/details|summary/g, "div"), format: 1 }
    }]);
}

