        <h3 style="border-bottom:2px solid #00008B; color:#000000; margin:0; text-transform:uppercase;">${p.item || 'Equipment'}</h3>
        <p style="font-size:0.9em; margin:5px 0; color: #000000;">
          <b>Mass:</b> ${p.mass || 0} | <b>Cost:</b> ${p.cost || 0} | <b>Affiliation:</b> ${p.affiliation || '—'}
        </p>
        <div style="margin-top:8px; border-top:1px solid #000000; font-size:0.95em; color: #000000; padding-top:5px;">
          ${p.notes || ""}
        </div>
      </div>`
  };

  // -----------------------------
  // MAIN LOGIC
  // -----------------------------
  const input = document.createElement("input");
  input.type = "file";
  input.accept = ".xml";

  input.onchange = async () => {
    const file = input.files[0];
    if (!file) return;

    const xmlText = await file.text();
    const parser = new DOMParser();
    const xml = parser.parseFromString(xmlText, "text/xml");

    const records = Array.from(xml.querySelectorAll("item [tagname^='id-'], item *"))
                         .filter(n => n.tagName.startsWith("id-"));

    if (!records.length) {
      ui.notifications.error("No item records found. Ensure your XML tags start with 'id-'.");
      return;
    }

    const folderIds = {};
    for (const cat of ALLOWED_TYPES) folderIds[cat] = await getOrCreateFolder(cat);

    const itemsToCreate = [];

    for (const record of records) {
      const typeNode = record.querySelector("item_type_listvalue");
      const itemKind = typeNode?.textContent?.trim();

      if (!ALLOWED_TYPES.includes(itemKind)) continue;

      const name = record.querySelector("name")?.textContent?.trim() ?? record.tagName;
      const rawData = extractRawData(record);

      const systemProps = { name: name };
      const map = FIELD_MAPS[itemKind];

      for (let [xmlTag, csbKey] of Object.entries(map)) {
        systemProps[csbKey] = rawData[xmlTag] !== undefined ? rawData[xmlTag] : "";
      }

      const finalHTML = TEMPLATES[itemKind](systemProps);

      itemsToCreate.push({
        name,
        type: ITEM_TYPE,
        img: ICONS[itemKind] || "icons/svg/item-bag.svg",
        folder: folderIds[itemKind],
        system: {
          description: finalHTML,
          props: systemProps
        }
      });
    }

    if (itemsToCreate.length > 0) {
      await Item.createDocuments(itemsToCreate);
      ui.notifications.info(`Successfully imported ${itemsToCreate.length} items.`);
    } else {
      ui.notifications.warn("No items matching Weapon, Armour, or Equipment were found.");
    }
  };

  input.click();

  function extractRawData(recordNode) {
    const data = {};
    for (const el of recordNode.children) {
      let value = el.textContent?.trim();
      const type = el.getAttribute("type");
      if (type === "number") value = Number(value) || 0;
      if (type === "formattedtext") value = el.innerHTML.trim();
      data[el.tagName] = value;
    }
    return data;
  }
})();

